/* Pure matching logic (no DOM) so it can be unit-tested with Node. */
(function (root) {
  "use strict";

  var CATEGORIES = [
    { id: "OPEN", label: "General (Open)" },
    { id: "EW", label: "EWS" },
    { id: "SE", label: "SEBC" },
    { id: "SC", label: "SC" },
    { id: "ST", label: "ST" }
  ];
  var QUOTA_LABELS = {
    GQ: "GQ – Government quota",
    MQ: "MQ – Management quota",
    NQ: "NQ – NRI quota",
    LQ: "LQ",
    AQ: "AQ"
  };
  var CLOSE_MARGIN = 20; // marks below last closing score still shown as "close"

  /** Latest-first list of {year, cell, category, fellBack} for one college/quota/category.
   *  If the category was published in no year, falls back to OPEN and says so. */
  function history(college, quota, cat) {
    var byYear = college.quotas[quota];
    if (!byYear) return [];
    var years = Object.keys(byYear).sort().reverse();
    var hasCat = years.some(function (y) { return byYear[y][cat] && byYear[y][cat].score != null; });
    var use = hasCat ? cat : "OPEN";
    return years.map(function (y) {
      var cell = byYear[y][use];
      return cell && cell.score != null ? { year: y, cell: cell, category: use, fellBack: use !== cat } : null;
    }).filter(Boolean);
  }

  /** Compare a NEET score with the most recent published closing score. */
  function evaluate(college, opts) {
    var hist = history(college, opts.quota, opts.category);
    if (!hist.length) return null;
    var ref = hist[0];
    var closing = ref.cell.score;
    if (closing == null) return null;
    var margin = opts.score - closing;
    var status = margin >= 0 ? "eligible" : margin >= -CLOSE_MARGIN ? "close" : "below";
    return { college: college, history: hist, ref: ref, closing: closing, margin: margin, status: status };
  }

  function search(colleges, opts) {
    var q = (opts.query || "").trim().toLowerCase();
    var out = [];
    colleges.forEach(function (c) {
      if (c.course !== opts.course) return;
      if (q && c.name.toLowerCase().indexOf(q) < 0 && c.code.toLowerCase().indexOf(q) < 0) return;
      var r = evaluate(c, opts);
      if (r) out.push(r);
    });
    var rank = { eligible: 0, close: 1, below: 2 };
    out.sort(function (a, b) {
      if (rank[a.status] !== rank[b.status]) return rank[a.status] - rank[b.status];
      // best colleges you can get first; for "close"/"below", nearest cut-off first
      return a.status === "eligible" ? b.closing - a.closing : a.closing - b.closing;
    });
    return out;
  }

  function quotasFor(colleges, course) {
    var set = {};
    colleges.forEach(function (c) {
      if (c.course === course) Object.keys(c.quotas).forEach(function (q) { set[q] = 1; });
    });
    var order = ["GQ", "LQ", "AQ", "MQ", "NQ"];
    return order.filter(function (q) { return set[q]; });
  }

  var api = { CATEGORIES: CATEGORIES, QUOTA_LABELS: QUOTA_LABELS, CLOSE_MARGIN: CLOSE_MARGIN,
              history: history, evaluate: evaluate, search: search, quotasFor: quotasFor };
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  else root.MedEdfillLogic = api;
})(typeof window !== "undefined" ? window : this);

